INSERT INTO "public"."devotional_plans" ("id", "title", "description", "cover_image", "completions", "tags", "status", "total_days", "author_id", "created_at", "updated_at") VALUES ('163b438c-8214-4a0d-a567-dd289b28076f', 'Strength for Difficult Days', 'When life feels heavy, this plan reminds you where real strength comes from.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/a06f1402-6a12-4d6f-a3fb-8429d5d91da4.jpg', '1', ARRAY['Prayer','Faith','Hope','Healing','Gratitude','Peace','Wisdom','Leadership','Family','Discipleship'], 'published', '2', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-02-17 11:07:17.873753+00', '2026-03-03 16:35:11.464173+00'), ('2b9ef9c5-3e11-4c52-8d17-9b6ea0c1a101', 'Walking with God in Uncertain Times', 'A 5-day devotional for seasons when answers feel distant and the next step is unclear. Each day helps you practice trust, receive peace, and move forward with steady hope in God.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/TimelineCovers.pro_religious-christian-believe-facebook-cover.jpg', '0', ARRAY['trust','faith','hope'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-03 17:21:14.506976+00', '2026-03-03 17:21:14.506976+00'), ('31f0b1f5-d517-4ab2-b370-6739b30f8e05', 'Walking Through Anxiety with God', 'An honest three-day journey for anyone battling fear, overthinking, or uncertainty. Learn how Scripture invites us to exchange anxiety for trust.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/81dd7b23-6c6f-482a-b345-567ec24594fc.jpg', '1', ARRAY['Prayer','Discipleship','Healing','Gratitude','Peace','Hope','Leadership','Family','Faith','Wisdom'], 'published', '3', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-02-16 16:41:37.379677+00', '2026-03-04 18:13:06.583618+00'), ('3d5704ea-4efe-415b-9cf3-3c58a39272a9', 'Loving Others Like Christ', 'A practical look at reflecting Christ’s love in everyday relationships.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/327b01b6-baa5-4296-8520-adce65fdcc0d.jpg', '0', ARRAY['Prayer','Family','Leadership','Hope','Healing','Gratitude','Peace','Wisdom','Discipleship','Faith'], 'published', '3', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-02-17 16:27:21.397913+00', '2026-02-17 16:30:31.631436+00'), ('3fca3c7a-87fd-4db2-a99c-95ab2ab4b202', 'Practicing Gratitude Daily', 'A 5-day journey that trains your heart to notice God''s goodness in both ordinary and difficult moments. Through simple daily practices, this plan helps gratitude become a lasting rhythm instead of a passing feeling.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/Red%20Hearts%20Background%20Wallpaper%20Love%20Covers.jpg', '0', ARRAY['gratitude','joy','prayer'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-03 17:21:14.506976+00', '2026-03-03 17:21:14.506976+00'), ('4d25c35b-52ef-4e59-b8d3-c9a1ab8ac303', 'Rest for the Weary Soul', 'A 5-day devotional for those carrying pressure, fatigue, and emotional noise. It points you to the rest Jesus offers and guides you toward practical rhythms that renew your soul.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/HD%20Love%20Cover%20Wallpaper.jpg', '0', ARRAY['rest','peace','sabbath'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-03 17:21:14.506976+00', '2026-03-03 17:21:14.506976+00'), ('5342820f-f77d-46a6-b56d-6fbef2d6ee80', 'Word of God', 'Studying the Bible to understand God’s Word.', null, '0', ARRAY['Wisdom'], 'draft', '7', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-02-23 15:26:03.337845+00', '2026-02-23 15:26:03.337845+00'), ('53e3d108-9de7-4be0-8d53-15f3737ee404', 'Growing in Wisdom', 'A 5-day devotional on making wise choices through humble dependence on God. You will focus on listening well, speaking carefully, and building daily habits that reflect biblical wisdom.', null, '0', ARRAY['wisdom','proverbs','character'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-03 17:21:14.506976+00', '2026-03-03 17:21:14.506976+00'), ('68479f74-cb73-4b0f-8a2e-cd3a0f6f9505', 'Love in Action', 'A 5-day devotional about turning belief into practical love for God and neighbor. Each day invites you to forgive, serve, and speak life in ways that make Christ''s love visible.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/coverof1.jpg', '0', ARRAY['love','service','community'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-03 17:21:14.506976+00', '2026-03-03 17:21:14.506976+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1001', 'Prayer That Changes You', 'A 5-day devotional on honest prayer, daily surrender, and growing trust in God''s presence. Each day helps you bring real burdens to the Lord and respond with practical faith.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1001.jpg', '0', ARRAY['prayer','surrender','faith'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1002', 'Courage in Everyday Battles', 'A 5-day devotional for moments when fear, opposition, or uncertainty feel overwhelming. You will learn to stand firm in God''s strength and move forward with courage.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1002.jpg', '1', ARRAY['courage','strength','faith'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-05 15:24:55.10153+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1003', 'Healing from Anxiety', 'A 5-day devotional that guides anxious hearts toward prayerful peace and renewed perspective. Through Scripture and reflection, it helps you exchange worry for trust.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1003.jpg', '0', ARRAY['anxiety','peace','trust'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1004', 'Living with Eternal Perspective', 'A 5-day devotional about seeing today''s decisions through the lens of eternity. It encourages wise priorities, steady hope, and faithful living in every season.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1004.jpg', '0', ARRAY['eternity','hope','wisdom'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1005', 'Faithful in Small Things', 'A 5-day devotional on everyday obedience and integrity in ordinary moments. It reminds you that God forms deep character through consistent faithfulness.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1005.jpg', '0', ARRAY['faithfulness','obedience','character'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1006', 'Hearing God in Scripture', 'A 5-day devotional focused on listening to God through His Word with attention and humility. Each day offers practical steps for reading, reflecting, and responding.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1006.jpg', '0', ARRAY['scripture','listening','discipleship'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1007', 'Freedom from Comparison', 'A 5-day devotional for breaking free from insecurity, envy, and measuring yourself against others. It points you to identity, purpose, and confidence in Christ.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1007.jpg', '0', ARRAY['identity','comparison','freedom'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1008', 'Contentment in Every Season', 'A 5-day devotional on learning contentment whether life feels abundant or limited. It helps you practice gratitude, trust, and peace in changing circumstances.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1008.jpg', '0', ARRAY['contentment','gratitude','trust'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-04 11:52:41.672629+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1009', 'The Way of Forgiveness', 'A 5-day devotional about healing relationships through gospel-shaped forgiveness. It encourages honest prayer, humility, and courageous steps toward reconciliation.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e1009.jpg', '1', ARRAY['forgiveness','healing','relationships'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-11 17:17:06.982662+00'), ('7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e100a', 'Hope for the Next Chapter', 'A 5-day devotional for transitions, endings, and new beginnings. It helps you anchor your expectations in God''s faithfulness while stepping into what is next.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/7a1f2b7e-0d21-4b2a-8a01-3a6c8d9e100a.jpg', '1', ARRAY['hope','transition','new-beginnings'], 'published', '5', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-03-04 11:52:41.058384+00', '2026-03-11 16:32:04.722218+00'), ('bdfac04b-d7a4-4338-80cc-b0dc9c1d7468', 'Rediscovering Your First Love', 'A devotional about renewing passion for Christ and returning to intimacy with Him.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/c48ff806-131d-4a8d-9b9c-dcd88ef9a2fc.jpg', '1', ARRAY['Prayer','Hope','Wisdom','Leadership','Discipleship'], 'published', '3', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-02-16 16:47:46.035255+00', '2026-03-04 17:13:37.018623+00'), ('d41fb2ab-636e-40ee-9d10-b37db52d1211', 'Growing Through Waiting', 'For those in seasons of delay, silence, or unanswered prayer. Discover how waiting is not wasted.', 'https://ujdyhgasuwikfvldhxnb.supabase.co/storage/v1/object/public/plan_images/ffaec876-14da-4080-9dc9-82cb4bc9d42e/6e844564-98fd-4f34-9979-ae623e3fa661.jpg', '1', ARRAY['Prayer','Family','Leadership','Healing','Hope','Wisdom','Discipleship'], 'published', '2', 'ffaec876-14da-4080-9dc9-82cb4bc9d42e', '2026-02-16 20:40:55.541099+00', '2026-03-04 16:34:12.601803+00');
